<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { Plus, Search, Users } from 'lucide-vue-next'
import { useApi, refreshData } from '../composables/query'
import { patch, post, api } from '../services/api'
import { useSession } from '../stores/session'
import type { Employee, Lookup } from '../types'
import AsyncState from '../components/AsyncState.vue'
import DataTable from '../components/DataTable.vue'
import EmployeeAvatar from '../components/EmployeeAvatar.vue'
import ConfirmationDialog from '../components/ConfirmationDialog.vue'
const session=useSession(),route=useRoute(),teamView=computed(()=>route.path==='/team'), search=ref(''),page=ref(0),peopleStatus=ref<'ACTIVE'|'INACTIVE'>('ACTIVE')
const {data,loading,error,refresh}=useApi<{items:Employee[];total:number}>(()=>`/employees?limit=20&offset=${page.value*20}&search=${encodeURIComponent(search.value)}&status=${teamView.value?'ACTIVE':peopleStatus.value}`)
const departments=useApi<Lookup[]>('/departments'),teams=useApi<Lookup[]>('/teams'),managers=useApi<{id:number;first_name:string;last_name:string;employee_number:string}[]>('/managers'),schedules=useApi<Lookup[]>('/schedules'),policies=useApi<{leave:Lookup[];mobile:Lookup[]}>('/policies'),types=useApi<Lookup[]>('/leave-types')
const open=ref(false),editing=ref<number|null>(null),busy=ref(false),failure=ref(''),actionError=ref(''),removeTarget=ref<Employee|null>(null),ledgerOpen=ref(false),ledger=ref<Record<string,unknown>[]>([]),selected=ref<Employee|null>(null)
const blank=()=>({identity_provider_subject:'',email:'',first_name:'',last_name:'',employee_number:'',manager_id:null as number|null,team_id:1,department_id:1,schedule_id:1,leave_policy_id:1,mobile_policy_id:1,employment_start_date:new Date().toISOString().slice(0,10),employment_end_date:null as string|null,timezone:'Europe/Sofia',status:'ACTIVE',roles:['EMPLOYEE']})
const form=reactive(blank()),adjustment=reactive({leave_type_id:1,year:new Date().getFullYear(),amount:1,reason:'',idempotency_key:crypto.randomUUID(),month:1}),operation=ref('adjustments')
watch(peopleStatus,()=>page.value=0)
function edit(employee?:Employee){Object.assign(form,blank());editing.value=employee?.id||null;if(employee)for(const key of Object.keys(form)){if(key in employee)(form as Record<string,unknown>)[key]=employee[key]}failure.value='';open.value=true}
async function save(){busy.value=true;failure.value='';try{const payload={...form,manager_id:form.manager_id||null};await(editing.value?patch(`/employees/${editing.value}`,payload):post('/employees',payload));open.value=false;await refreshData();session.message('Employee record saved.')}catch(e){failure.value=(e as Error).message}finally{busy.value=false}}
async function removeEmployee(){if(!removeTarget.value)return;busy.value=true;actionError.value='';try{await patch(`/employees/${removeTarget.value.id}`,{status:'INACTIVE'});removeTarget.value=null;await refreshData();session.message('Employee removed from active staff.')}catch(e){actionError.value=(e as Error).message}finally{busy.value=false}}
async function restoreEmployee(employee:Employee){busy.value=true;actionError.value='';try{await patch(`/employees/${employee.id}`,{status:'ACTIVE'});await refreshData();session.message('Employee restored.')}catch(e){actionError.value=(e as Error).message}finally{busy.value=false}}
async function showLedger(employee:Employee){selected.value=employee;failure.value='';ledgerOpen.value=true;try{ledger.value=await api(`/employees/${employee.id}/ledger`)}catch(e){failure.value=(e as Error).message}}
async function adjust(){if(!selected.value)return;busy.value=true;failure.value='';try{const body=operation.value==='adjustments'?{leave_type_id:adjustment.leave_type_id,year:adjustment.year,amount:adjustment.amount,reason:adjustment.reason,idempotency_key:adjustment.idempotency_key}:{leave_type_id:adjustment.leave_type_id,year:adjustment.year,month:adjustment.month,reason:adjustment.reason};await post(`/employees/${selected.value.id}/${operation.value}`,body);adjustment.idempotency_key=crypto.randomUUID();await showLedger(selected.value);await refreshData();session.message('Balance ledger updated.')}catch(e){failure.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><div class="eyebrow">PEOPLE MAKE THE DIFFERENCE</div><h1>{{teamView?'My team':'Employees'}}</h1><p>{{teamView?'Stay connected to your people and their plans.':'A thoughtful home for your employee records.'}}</p></div><button v-if="!teamView" class="btn primary" @click="edit()"><Plus :size="17"/>Add employee</button><RouterLink v-else to="/approvals" class="btn primary">Review requests</RouterLink></div><div v-if="!teamView" class="filter-tabs" role="group" aria-label="Employee status"><button :class="{selected:peopleStatus==='ACTIVE'}" @click="peopleStatus='ACTIVE'">Active</button><button :class="{selected:peopleStatus==='INACTIVE'}" @click="peopleStatus='INACTIVE'">Removed</button></div><p v-if="actionError" class="error-box" role="alert">{{actionError}}</p><div class="search-field"><Search :size="18"/><input v-model="search" aria-label="Search employees" placeholder="Find a teammate…" @input="page=0"></div><AsyncState :loading="loading" :error="error" :empty="!data?.items.length" @retry="refresh"><section class="panel"><DataTable :headers="teamView?['Teammate','Department','Team','Status']:['Employee','Department','Team','Status','Actions']"><tr v-for="person in data?.items" :key="person.id"><td><div class="person-line"><EmployeeAvatar :name="`${person.first_name} ${person.last_name}`"/><div><strong>{{person.first_name}} {{person.last_name}}</strong><small>{{person.email}}</small></div></div></td><td>{{departments.data.value?.find(d=>d.id===person.department_id)?.name}}</td><td>{{teams.data.value?.find(t=>t.id===person.team_id)?.name}}</td><td><span class="status" :class="person.status==='ACTIVE'?'approved':'cancelled'">{{person.status.toLowerCase()}}</span></td><td v-if="!teamView"><div class="button-row"><button class="text-link" @click="edit(person)">Edit</button><button v-if="person.status==='ACTIVE'&&person.id!==session.user?.id" class="text-link" @click="actionError='';removeTarget=person">Remove</button><button v-if="person.status==='INACTIVE'" class="text-link" :disabled="busy" @click="restoreEmployee(person)">Restore</button><button v-if="session.has('HR')" class="text-link" @click="showLedger(person)">Balances</button></div></td></tr></DataTable></section><div class="pagination"><span>{{data?.total}} employees</span><button class="btn secondary" :disabled="page===0" @click="page--">Previous</button><button class="btn secondary" :disabled="(page+1)*20>=(data?.total||0)" @click="page++">Next</button></div></AsyncState><ConfirmationDialog :open="open" :title="editing?'Edit employee':'Add employee'" @close="open=false"><form @submit.prevent="save"><div class="form-grid"><label>First name<input v-model="form.first_name" required maxlength="100"></label><label>Last name<input v-model="form.last_name" required maxlength="100"></label><label>Email<input v-model="form.email" type="email" required></label><label>Employee number<input v-model="form.employee_number" required></label></div><label>Clerk user ID<input v-model="form.identity_provider_subject" required :disabled="!!editing&&!session.has('ADMIN')"><span class="field-hint">The user_… identifier from your Clerk Dashboard. Existing accounts must be linked explicitly.</span></label><div class="form-grid"><label>Department<select v-model.number="form.department_id"><option v-for="d in departments.data.value" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label>Team<select v-model.number="form.team_id"><option v-for="t in teams.data.value?.filter(t=>t.department_id===form.department_id)" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label>Manager<select v-model.number="form.manager_id"><option :value="null">No manager</option><option v-for="manager in managers.data.value?.filter(manager=>manager.id!==editing)" :key="manager.id" :value="manager.id">{{manager.first_name}} {{manager.last_name}} ({{manager.employee_number}})</option></select></label><label>Timezone<input v-model="form.timezone" required></label><label>Employment start<input v-model="form.employment_start_date" type="date" required></label><label>Status<select v-model="form.status"><option>ACTIVE</option><option>INACTIVE</option></select></label><label>Work schedule<select v-model.number="form.schedule_id"><option v-for="s in schedules.data.value" :key="s.id" :value="s.id">{{s.name}}</option></select></label><label>Leave policy<select v-model.number="form.leave_policy_id"><option v-for="p in policies.data.value?.leave" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>Mobile-work policy<select v-model.number="form.mobile_policy_id"><option v-for="p in policies.data.value?.mobile" :key="p.id" :value="p.id">{{p.name}}</option></select></label></div><fieldset v-if="session.has('ADMIN')"><legend>Roles</legend><label v-for="role in ['EMPLOYEE','MANAGER','HR','ADMIN']" :key="role" class="checkbox-label"><input v-model="form.roles" type="checkbox" :value="role">{{role}}</label></fieldset><p v-if="failure" class="error-box" role="alert">{{failure}}</p><div class="form-actions"><button class="btn primary" :disabled="busy">{{busy?'Saving…':'Save employee'}}</button></div></form></ConfirmationDialog><ConfirmationDialog :open="ledgerOpen" :title="`${selected?.first_name}’s leave ledger`" @close="ledgerOpen=false"><form @submit.prevent="adjust"><div class="form-grid"><label>Operation<select v-model="operation"><option value="adjustments">Manual adjustment</option><option value="entitlements">Grant policy entitlement</option><option value="carryover">Transfer carryover</option></select></label><label>Leave type<select v-model.number="adjustment.leave_type_id"><option v-for="t in types.data.value?.filter(t=>t.tracks_balance)" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label>Year<input v-model.number="adjustment.year" type="number" min="2000" max="2200" required></label><label v-if="operation==='adjustments'">Days (+ / −)<input v-model.number="adjustment.amount" type="number" step="0.5" required></label><label v-if="operation==='entitlements'">Accrual month<input v-model.number="adjustment.month" type="number" min="1" max="12"></label></div><label>Documented reason<textarea v-model="adjustment.reason" required minlength="3" maxlength="1000"/></label><p v-if="failure" class="error-box" role="alert">{{failure}}</p><button class="btn primary" :disabled="busy">Record ledger transaction</button></form><div class="summary-divider"/><DataTable :headers="['Date','Type','Days']"><tr v-for="entry in ledger" :key="String(entry.id)"><td>{{entry.effective_date}}</td><td>{{entry.transaction_type}}</td><td>{{entry.amount}}</td></tr></DataTable></ConfirmationDialog><ConfirmationDialog :open="!!removeTarget" title="Remove employee" :description="removeTarget?`Remove ${removeTarget.first_name} ${removeTarget.last_name} from active staff? Their sign-in will be blocked. Requests and balances stay in the audit history.`:undefined" @close="removeTarget=null"><p v-if="actionError" class="error-box" role="alert">{{actionError}}</p><div class="form-actions"><button type="button" class="btn secondary" @click="removeTarget=null">Keep employee</button><button type="button" class="btn primary" :disabled="busy" @click="removeEmployee">{{busy?'Removing…':'Remove employee'}}</button></div></ConfirmationDialog></template>
